    const members = c.members.map((m) => m.personId);
    if (c.leadId === self.id || members.includes(self.id)) {
      if (c.leadId !== null) ids.add(c.leadId);
      members.forEach((id) => ids.add(id));
    }
  }
  return (p) => ids.has(p.id);
}
